
(function(root){'use strict';const {Brawler,ZONES}=root.NeonCombat,P=Brawler.prototype,spawn=P.spawnZone,reinforce=P.reinforce,spawnFin=P.spawnFinancial;
P.spawnZone=function(){if(!this.hotelRoute||![5,6].includes(this.zone))return spawn.call(this);if(this.zone===5){spawn.call(this);this.patrons=[];this.props=[];this.event('zone',{name:'MIDNIGHT CLUB'});return;}const z=ZONES[6];this.player.y=this.player.prevY=375;this.enemies=[];this.pending=[];this.props=[];this.patrons=[];this.items=[];this.projectiles=[];this.alleyIntro=null;this.bossEnding=null;this.zoneClear=false;this.bossStage=3;this.alleyPhase='vip';this.progressX=this.player.x;for(const [type,dx,wait] of [['boss',1080,true],['thug',970,true],['knifeThug',1190,true],['thug',400,false],['knifeThug',600,false],['enforcer',770,false]]){const e=this.deployEnemy({type,x:z.start+dx,y:wait?350:380});e.y=e.prevY=wait?350:380;e.dormant=wait;e.alleyWaiting=wait;e.vipEscort=wait&&type!=='boss';e.activeAt=0;if(type==='boss')e.weapon='knife';}this.items.push({x:z.start+180,y:375,kind:'fullHeal',value:125});this.event('zone',{name:'MIDNIGHT CLUB / VIP'});};
P.reinforce=function(){if(!(this.hotelRoute&&this.zone===6&&this.alleyPhase==='vip'))return reinforce.call(this);const boss=this.enemies.find(e=>e.type==='boss');if(boss&&boss.hp<=0){this.alleyPhase='fight';return reinforce.call(this);}const waiting=this.enemies.filter(e=>e.alleyWaiting&&e.hp>0);if(waiting.length&&!this.enemies.some(e=>e.hp>0&&!e.alleyWaiting&&!e.fleeing)&&this.settledDefeats()){for(const e of waiting){e.dormant=false;e.alleyWaiting=false;e.cd=.8;e.activeAt=0;e.dir=-1;}this.alleyPhase='fight';this.event('boss');}};
P.spawnFinancial=function(){spawnFin.call(this);if(this.hotelRoute&&this.zone===7){this.carX=ZONES[7].start+610;this.event('zone',{name:'FINANCIAL DISTRICT / GETAWAY CRASH'});}};
})(typeof window!=='undefined'?window:globalThis);
